<template><div class="app-container ps-page"><h2>成员与业务资格</h2><el-alert title="账号、密码、角色和部门由平台用户管理维护；此页只维护知识空间与知识库额度。" type="info" :closable="false" class="ps-section"/><el-alert v-if="error||pageError" :title="error||pageError" type="error" :closable="false"/><el-form inline><el-form-item label="成员"><el-input v-model="query.keyword" clearable @keyup.enter="load(true)"/></el-form-item><el-form-item label="所属空间"><el-select v-model="query.spaceId" clearable><el-option v-for="s in spaces.filter(s=>s.type!=='PERSONAL')" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="启用状态"><el-select v-model="query.status" clearable><el-option label="已启用" value="0"/><el-option label="已停用" value="1"/></el-select></el-form-item><el-button @click="load(true)">查询</el-button><el-button @click="resetSearch">重置</el-button></el-form><el-table :data="rows" v-loading="loading"><el-table-column prop="userName" label="平台账号" min-width="180"/><el-table-column prop="nickName" label="姓名" min-width="160"/><el-table-column label="平台状态" width="110"><template #default="{row}">{{row.platformStatus==='0'?'正常':row.platformStatus==='1'?'已停用':'未返回'}}</template></el-table-column><el-table-column label="业务资格" width="110"><template #default="{row}">{{row.enabled?'已启用':'未启用'}}</template></el-table-column><el-table-column label="空间" min-width="200"><template #default="{row}">{{(row.spaceIds||[]).map((id:Id)=>spaces.find(s=>String(s.id)===String(id))?.name||id).join('、')}}</template></el-table-column><el-table-column label="对话额度与请求" min-width="260"><template #default="{row}"><QuotaScopeSummary :quota="row.usage?.llm"/></template></el-table-column><el-table-column label="向量额度与请求" min-width="260"><template #default="{row}"><QuotaScopeSummary :quota="row.usage?.embedding"/></template></el-table-column><el-table-column label="聊天请求" width="170"><template #default="{row}">今日 {{row.usage?.chatRequestCount?.toLocaleString()??'未返回'}} · 累计 {{row.usage?.totalChatRequestCount?.toLocaleString()??'未返回'}}</template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="180"/><el-table-column label="操作" width="280"><template #default="{row}"><el-button v-hasPermi="['paismart:space:member']" link @click="edit(row)">空间资格</el-button><el-button v-hasPermi="['paismart:usage:adjust']" link @click="credit(row)">追加额度</el-button><el-button v-hasPermi="['paismart:usage:adjust']" link @click="editPolicy(row)">额度政策</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="query.pageSize" :total="total" layout="total,prev,pager,next" @current-change="load()"/><el-dialog v-model="spaceOpen" :title="`空间资格 · ${selected?.userName||''}`" width="760px"><el-form label-width="100px"><el-form-item label="所属空间"><el-table :data="assignments"><el-table-column label="空间" min-width="170"><template #default="{row}"><el-checkbox v-model="row.selected">{{row.name}}</el-checkbox></template></el-table-column><el-table-column label="允许上传" width="110"><template #default="{row}"><el-checkbox v-model="row.uploadAllowed" :disabled="!row.selected"/></template></el-table-column><el-table-column label="空间管理" width="110"><template #default="{row}"><el-checkbox v-model="row.managerAllowed" :disabled="!row.selected"/></template></el-table-column></el-table></el-form-item><el-form-item label="主空间"><el-select v-model="primarySpaceId" clearable><el-option v-for="s in spaces.filter(v=>assignments.some(a=>a.selected&&a.spaceId===v.id))" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="spaceOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveSpaces">保存</el-button></template></el-dialog><el-dialog v-model="creditOpen" :title="`追加额度 · ${selected?.userName||''}`" width="560px"><el-form label-width="120px"><el-form-item label="对话 Token"><el-input-number v-model="creditForm.llmTokens" :min="0" :max="1000000000" :precision="0"/></el-form-item><el-form-item label="向量 Token"><el-input-number v-model="creditForm.embeddingTokens" :min="0" :max="1000000000" :precision="0"/></el-form-item><el-form-item label="追加原因" required><el-input v-model="creditForm.reason" type="textarea" maxlength="500"/></el-form-item></el-form><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><template #footer><el-button @click="creditOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitCredit">确认追加</el-button></template></el-dialog><el-dialog v-model="policyOpen" :title="'额度政策 · '+(policyMember?.userName||'')" width="580px"><el-form v-if="policy" label-width="120px"><el-form-item label="用量模式"><el-select v-model="policy.mode"><el-option label="余额扣减" value="BALANCE"/><el-option label="每日限额" value="DAILY"/></el-select></el-form-item><el-form-item label="每日对话 Token"><el-input-number v-model="policy.dailyLlmTokens" :min="0" :max="1000000000" :precision="0"/></el-form-item><el-form-item label="每日向量 Token"><el-input-number v-model="policy.dailyEmbeddingTokens" :min="0" :max="1000000000" :precision="0"/></el-form-item></el-form><el-alert v-if="policyError" :title="policyError" type="error" :closable="false"/><template #footer><el-button @click="policyOpen=false">关闭</el-button><el-button type="primary" :disabled="!policy" :loading="policySaving" @click="submitPolicy">保存政策</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref, shallowRef, watch } from 'vue'
import { getQuotaPolicy,saveQuotaPolicy,grantCredits, listMembers, listSpaces, saveMemberSpaces } from '@/api/paismart/spaces'
import { newKey } from '@/api/paismart/client'
import type { Id,Member,Space } from '@/types/paismart'
import { errorText,usePage } from '../composables/usePage'
import QuotaScopeSummary from '../components/QuotaScopeSummary.vue'
import '../common.css'
const {rows,total,query,loading,error,load}=usePage(listMembers),spaces=shallowRef<Space[]>([]),selected=shallowRef<Member>(),spaceOpen=ref(false),creditOpen=ref(false),assignments=ref<{spaceId:Id;name:string;selected:boolean;uploadAllowed:boolean;managerAllowed:boolean}[]>([]),primarySpaceId=ref<Id>(),pageError=ref(''),formError=ref(''),saving=ref(false),creditForm=ref({llmTokens:0,embeddingTokens:0,reason:''});const policyOpen=ref(false),policy=ref<{mode:string;dailyLlmTokens:number;dailyEmbeddingTokens:number;rowVersion:number}>();let creditKey=newKey()
const policyMember=shallowRef<Member>(),policyError=ref(''),policySaving=ref(false)
let policyActive=true,policyRevision=0
function policyCurrent(revision:number,id:Id){return policyActive&&policyOpen.value&&revision===policyRevision&&String(policyMember.value?.id)===String(id)}
watch(policyOpen,open=>{if(!open){policyRevision++;policy.value=undefined;policyError.value='';policySaving.value=false}},{flush:'sync'})
onBeforeUnmount(()=>{policyActive=false;policyRevision++})
function resetSearch(){query.value.keyword=undefined;query.value.spaceId=undefined;query.value.status=undefined;void load(true)}
function edit(row:Member){selected.value=row;assignments.value=spaces.value.filter(s=>s.type!=='PERSONAL'&&s.canManage!==false).map(s=>{const existing=row.assignments?.find(a=>String(a.spaceId)===String(s.id));return {spaceId:s.id,name:s.name,selected:!!existing||(row.spaceIds||[]).includes(s.id),uploadAllowed:existing?.uploadAllowed??true,managerAllowed:existing?.managerAllowed??false}});primarySpaceId.value=row.primarySpaceId;formError.value='';spaceOpen.value=true}
function credit(row:Member){selected.value=row;creditForm.value={llmTokens:0,embeddingTokens:0,reason:''};creditKey=newKey();formError.value='';creditOpen.value=true}
async function saveSpaces(){if(!selected.value)return;saving.value=true;formError.value='';try{await saveMemberSpaces(selected.value,assignments.value.filter(a=>a.selected).map(({spaceId,uploadAllowed,managerAllowed})=>({spaceId,uploadAllowed,managerAllowed})),assignments.value.some(a=>a.selected&&a.spaceId===primarySpaceId.value)?primarySpaceId.value:undefined);spaceOpen.value=false;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function submitCredit(){if(!selected.value)return;if(!creditForm.value.reason.trim()||creditForm.value.llmTokens+creditForm.value.embeddingTokens<=0){formError.value='请填写追加原因，并至少追加一种额度';return}saving.value=true;formError.value='';try{await grantCredits(selected.value.id,creditForm.value,creditKey);creditOpen.value=false;await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function editPolicy(row:Member){
  const revision=++policyRevision,member={...row}
  policyMember.value=member;policy.value=undefined;policyError.value='';policySaving.value=false;policyOpen.value=true
  try{const result=await getQuotaPolicy(member.id);if(policyCurrent(revision,member.id))policy.value={...result.data}}
  catch(e){if(policyCurrent(revision,member.id))policyError.value=errorText(e)}
}
async function submitPolicy(){
  if(!policyActive||!policyOpen.value||!policyMember.value||!policy.value||policySaving.value)return
  const revision=policyRevision,id=policyMember.value.id,input={...policy.value},submitted=JSON.stringify(input)
  policySaving.value=true;policyError.value=''
  try{
    await saveQuotaPolicy(id,input)
    if(!policyActive)return
    // 已受理的写入仍回读列表；旧回执不能关闭新成员或后来编辑的表单。
    if(policyCurrent(revision,id)&&JSON.stringify(policy.value)===submitted)policyOpen.value=false
    await load()
  }catch(e){if(policyCurrent(revision,id))policyError.value=errorText(e)}
  finally{if(policyCurrent(revision,id))policySaving.value=false}
}
onMounted(async()=>{void load();try{spaces.value=(await listSpaces()).rows}catch(e){pageError.value=errorText(e)}})
</script>
